#!/bin/bash
# Runs the additive notes backfill inside the PRODUCTION backend container.
# Inserts 23 missing conference notes, updates 2 stale ones, deletes nothing.
set -e
cd "$(dirname "$0")/.."
railway ssh -s mono-mind-backend -e production -- bash -c "echo  | base64 -d > /tmp/bf.py && cd /app && (python3 /tmp/bf.py 2>/dev/null || /opt/venv/bin/python /tmp/bf.py)"
